  civil : Nat → Option CivilTime := fun _ => none
  notInSession : Bool := false
  outsideMargin : Bool := false
  pupilsInClass : Bool := true

def build (s : Setup) : Trace :=
  Build.trace steps 0 (Units.seconds 1) fun k t =>
    let x := Build.withKin
      (Build.user 1 s.xClasses (s.xPos k) (headingAt k) (Units.metresPerSecond 3) (cm 225, cm 90, cm 75))
      fun kin => { kin with yawRate := some (yawAt k) }
    let c := Build.user 2 s.childClasses (if s.childNear k then nearChild else farChild)
      Build.north Q.zero (cm 20, cm 20, cm 60)
    Build.scene t (some 1) [x, c] roads (s.zones ++ s.beacons k) (s.occupancy.map (· k))
      { civilTime := s.civil k }
      [ ("asm.school_not_in_session_day", s.notInSession)
      , ("asm.outside_school_operation_margin", s.outsideMargin)
      , ("asm.pupils_in_class", s.pupilsInClass) ]

/-- `forbid` (violated): x (ru.motor_vehicle) makes a U-turn on a lane governed by a school zone sign z; a ru.child stands within p.child_presence_reach of z's lane at every observation, asm.school_not_in_session_day and asm.outside_school_operation_margin are declared false, and a speed limit beacon governing the lane is flashing. -/
def forbidTrace : Trace := build {}

/-- `permit` (compliant): x makes a U-turn on z's lane while no ru.child lies within p.child_presence_reach of any region z governs at any observation of the act. The child stands beside lane 13, outside the zone. -/
def permitTrace : Trace := build { childNear := fun _ => false }

/-- `idle` (not_applicable): x makes a U-turn on a street no school zone or school crossing zone sign governs. The sign governs lanes 12 and 13 only. -/
def idleTrace : Trace := build { zones := [schoolZone [12, 13] (some {})] }

/-- `blind` (unknown): x drives along z's lane with children on the sidewalk and turns about, but its yaw rate is missing, so whether a U-turn was made is unknown. -/
def blindTrace : Trace := Build.masked (Build.manifest ["kin.yaw_rate"]) forbidTrace

/-- `occasion_d3` (violated): Baseline as in forbid (children present, school in session, inside the operation margin, beacon flashing): x begins its U-turn on z's lane and completes it on a lane beyond the stretch z governs; it occupied z's lane for part of the act only. -/
def occasion_d3Trace : Trace :=
  build { xPos := fun k => if 26 ≤ k then (m 102, m 6) else (m 98, m 2) }

/-- `occasion_d3_outside` (not_applicable): x drove along z's lane, left the governed stretch, and only afterwards, on a lane no zone sign governs, makes its U-turn: it was in the zone before the act began only. -/
def occasion_d3_outsideTrace : Trace :=
  build { xPos := fun k => if k ≤ 22 then (m 90, m 2) else if k ≤ 25 then (m 150, m 2) else (m 150, m 6) }

/-- `occasion_d5` (violated): U-turn on z's lane; no ru.child is within p.child_presence_reach at the first observations of the act, then a child walks up beside the lane before the act is recognized; the other alternatives fail throughout. -/
def occasion_d5Trace : Trace := build { childNear := fun k => 26 ≤ k }

/-- `occasion_d5_outside` (compliant): Children stood beside z's lane before the act began and left; at every observation of the U-turn none lies within p.child_presence_reach; the other alternatives fail. -/
def occasion_d5_outsideTrace : Trace := build { childNear := fun k => k ≤ 22 }

/-- `occasion_d8` (violated): A beacon governs the region x occupies at the start of the U-turn only; x ends the turn on a region no beacon governs; asm.pupils_in_class holds and the beacon is not flashing; z's conditions hold; children present, school in session, inside the margin: neither (d) nor (e) covers the whole act. The beacon governs lane 14, which x straddles with lane 10 until 25 s. -/
def occasion_d8Trace : Trace :=
  build { xPos := (fun k => if 26 ≤ k then onW else straddle)
          occupancy := some (fun k => if 26 ≤ k then [(1, 11)] else [(1, 10), (1, 14)])
          beacons := (fun _ => [beaconOn [14] false]) }

/-- `occasion_d8_outside` (compliant): No beacon governs the region x occupied before the act; a non-flashing beacon governs every region x occupies during the U-turn and asm.pupils_in_class holds throughout it; children present. x is on lane 10 alone until 22 s, then straddles lanes 10 and 14, the beacon's. -/
def occasion_d8_outsideTrace : Trace :=
  build { xPos := (fun k => if k ≤ 22 then onE else straddle)
          occupancy := some (fun k => if k ≤ 22 then [(1, 10)] else [(1, 10), (1, 14)])
          beacons := (fun _ => [beaconOn [14] false]) }

/-- `occasion_d10` (violated): A beacon governs z's lane and asm.pupils_in_class holds throughout; the beacon is not flashing for the first part of the U-turn and flashing for the rest; children present. The beacon governs lane 11. -/
def occasion_d10Trace : Trace := build { beacons := fun k => [beaconOn [11] (26 ≤ k)] }

/-- `occasion_d10_outside` (compliant): A beacon governs z's lane and asm.pupils_in_class holds throughout; the beacon was flashing before the act and is not flashing at any observation of the U-turn; children present. -/
def occasion_d10_outsideTrace : Trace := build { beacons := fun k => [beaconOn [11] (k ≤ 22)] }

/-- `occasion_d12` (violated): No beacon governs the region x occupies at the start of the U-turn, a flashing beacon governs the region it ends on; z's conditions do not hold throughout; children present, school in session, inside the margin. x ends on lane 13, which the beacon governs; it is 18:00. -/
def occasion_d12Trace : Trace :=
  build { xPos := (fun k => if 26 ≤ k then (m 102, m 6) else (m 98, m 2))
          zones := [schoolZone [10, 11] (some postedHours)]
          civil := (fun _ => clock 1080)
          beacons := (fun _ => [beaconOn [13] true]) }

/-- `occasion_d12_outside` (compliant): A beacon governed the region x occupied before the act; no beacon governs any region x occupies or z governs during the U-turn; z's conditions do not hold throughout; children present. The beacon governs lane 15, x's approach until 22 s. -/
def occasion_d12_outsideTrace : Trace :=
  build { xPos := (fun k => if k ≤ 22 then (m (-50), m 2) else defaultPos k)
          zones := [schoolZone [10, 11] (some postedHours)]
          civil := (fun _ => clock 1080)
          beacons := (fun _ => [beaconOn [15] true]) }

/-- `occasion_d13` (violated): No beacon; env.civil_time leaves z's posted window during the U-turn, so z's conditions do not hold for the first part of the act and hold for the rest; children present, school in session, inside the margin. It is 6:59 until 25 s and 7:00 from 26 s. -/
def occasion_d13Trace : Trace :=
  build { zones := [schoolZone [10, 11] (some postedHours)]
          beacons := (fun _ => [])
          civil := (fun k => clock (if 26 ≤ k then 420 else 419)) }

/-- `occasion_d13_outside` (compliant): No beacon; z's conditions held before the act and do not hold at any observation of the U-turn; children present. It is 15:59 until 22 s and 16:00 from 23 s. -/
def occasion_d13_outsideTrace : Trace :=
  build { zones := [schoolZone [10, 11] (some postedHours)]
          beacons := (fun _ => [])
          civil := (fun k => clock (if k ≤ 22 then 959 else 960)) }

/-- `branch_1` (compliant): x makes a U-turn on z's lane with children present while asm.school_not_in_session_day is declared true at every observation of the act. -/
def branch_1Trace : Trace := build { notInSession := true }

/-- `branch_2` (compliant): as forbid, but asm.outside_school_operation_margin is declared true throughout: exception (c). -/
def branch_2Trace : Trace := build { outsideMargin := true }

/-- `branch_3` (not_applicable): as forbid, but the school zone sign is an end sign. -/
def branch_3Trace : Trace := build { zones := [Build.zoneSign 100 [10, 11] .school true (some {})] }

/-- `branch_4` (not_applicable): as forbid, but the sign begins a pedestrian safety zone, not a school zone. -/
def branch_4Trace : Trace := build { zones := [Build.zoneSign 100 [10, 11] .pedestrianSafety false (some {})] }

/-- `branch_5` (not_applicable): as forbid, but x is a bicycle, no vehicle of DEF-NRS-484A-320. -/
def branch_5Trace : Trace := build { xClasses := [.bicycle] }

/-- `branch_6` (compliant): as forbid, but the pedestrian beside the lane is an adult: no child is present. -/
def branch_6Trace : Trace := build { childClasses := [.pedestrian] }

/-- `branch_7` (violated): a non-flashing beacon governs z's lanes, but the pupils are not in class: (d) fails, and the beacon defeats (e). -/
def branch_7Trace : Trace :=
  build { beacons := (fun _ => [beaconOn [10, 11] false]), pupilsInClass := false }

/-- `branch_8` (compliant): z's posted hours are over (18:00, no beacon), so (e) covers the act; an end sign 102 also governs z's lanes, unconditionally, and is no zone x turned in. -/
def branch_8Trace : Trace :=
  build { zones := [schoolZone [10, 11] (some postedHours), Build.zoneSign 102 [10, 11] .school true (some {})]
          beacons := (fun _ => [])
          civil := (fun _ => clock 1080) }

/-- `branch_9` (compliant): as branch_8, with a speed zone sign 102 governing z's lanes instead of the end sign. -/
def branch_9Trace : Trace :=
  build { zones := [schoolZone [10, 11] (some postedHours), Build.zoneSign 102 [10, 11] .speedZone false (some {})]
          beacons := (fun _ => [])
          civil := (fun _ => clock 1080) }

/-- `branch_10` (compliant): as branch_8, with an unconditional school zone sign 102 governing lanes 12 and 13, where x never is. -/
def branch_10Trace : Trace :=
  build { zones := [schoolZone [10, 11] (some postedHours), Build.zoneSign 102 [12, 13] .school false (some {})]
          beacons := (fun _ => [])
          civil := (fun _ => clock 1080) }

def witness (name : String) (τ : Trace) (expected : Verdict)
    (absent : List String := []) (boundary : String := "") : Scenario :=
  { name := name
    rule := "NRS_484B_363_3"
    trace := τ
    reading := {}          -- ignored by the gate: the run's reading is substituted
    manifest := Build.manifest absent
    grounding := [("x", 1)]
    expected := expected
    window := some (21000, 35000)
    boundary := boundary }

def scenarios : List Scenario :=
  [ witness "forbid" forbidTrace .violated
  , witness "permit" permitTrace .compliant
  , witness "idle" idleTrace .notApplicable
  , witness "blind" blindTrace (.unknown []) ["kin.yaw_rate"]
  , witness "occasion_d3" occasion_d3Trace .violated
